function addSong(l){catalog.push(l);try{localStorage.setItem('fm1-custom-songs',JSON.stringify(catalog.filter(x=>x.group==='My songs')))}catch{toast('Export your song file to keep it; browser storage is full.');}chooseLesson(catalog.length-1);renderLessons();}
