function setLearningPlan(plan){settings.practiceStyle='All';if(active||transition)stopTransport();settings.learningPlan=plan;saveQuiet();syncLearningPanel();}
function toggleLearningTopic(topic,on){settings.practiceStyle='All';const current=selectedTopics(settings),next=LEARNING_TOPICS.filter(t=>t===topic?on:current.includes(t));if(!next.length){toast('Keep at least one learning topic enabled.');return;}if(active||transition)stopTransport();settings.learningPlan='Custom mix';settings.learningTopics=next;saveQuiet();syncLearningPanel();}
