function drawStaff(t){const base=settings.wait?session.target?.onset||0:t-session.started;const dia=n=>Math.floor(n/12)*7+[0,0,1,1,2,3,3,4,4,5,5,6][n%12];for(const [y,hand,bottom]of [[66,'R',64],[125,'L',43]]){ctx.strokeStyle='#617b57';for(let i=0;i<5;i++){ctx.beginPath();ctx.moveTo(7,y+i*8);ctx.lineTo(233,y+i*8);ctx.stroke()}text(hand==='R'?'G':'F',11,y+23,19,'#92af82');for(const e of session.events.filter(e=>e.onset>=base-700&&e.onset<=base+2300))for(let k=0;k<e.notes.length;k++){if(e.hands[k]!==hand)continue;const x=70+(e.onset-base)*.0625,ny=y+32-(dia(e.notes[k])-dia(bottom))*4;if(x<25||x>228)continue;const py=clamp(ny,49,174);ctx.fillStyle=e.status[k]===1?'#5a9042':e.hands[k]==='L'?'#8ccfe4':'#c6ed9d';ctx.beginPath();ctx.ellipse(x,py,4.8,3,-.25,0,7);ctx.fill();ctx.strokeStyle=ctx.fillStyle;ctx.beginPath();ctx.moveTo(x+4,py);ctx.lineTo(x+4,py-18);ctx.stroke();if(ny>y+32)for(let ly=y+40;ly<=Math.min(ny,y+56);ly+=8){ctx.beginPath();ctx.moveTo(x-7,ly);ctx.lineTo(x+8,ly);ctx.stroke()}if([1,3,6,8,10].includes(e.notes[k]%12))text('#',x-12,py+3,10);}}box(69,48,1,127,'#b7e688');}
