function refreshPorts(){if(!midiAccess)return;const fill=(id,ports,previous,prompt)=>{const el=$(id);el.replaceChildren();const none=document.createElement('option');none.value='';none.textContent=prompt;el.append(none);for(const port of ports.values()){const option=document.createElement('option');option.value=port.id;option.textContent=port.name||port.id;el.append(option)}el.value=ports.has(previous)?previous:'';return el.value;};inputChoice=fill('midi-select',midiAccess.inputs,inputChoice,'Select keyboard input');fill('hardware-input',midiAccess.inputs,$('hardware-input').value,'FM-1 response input');fill('hardware-output',midiAccess.outputs,$('hardware-output').value,'Select FM-1 output');for(const input of midiAccess.inputs.values())input.onmidimessage=e=>receiveMidi(input.id,e.data,e.timeStamp);updateHardwarePorts();$('midi-connect').textContent=midiAccess.sysexEnabled?'↔ MIDI + SysEx':'↔ MIDI enabled';}
