async function receiveMidi(inputId,data,eventAt=now()){hardware.feed(inputId,data);if(data[0]===240){if(hardwareReceive&&inputId===$('hardware-input').value&&data[1]===67){try{importBank(new Uint8Array(data),'FM-1 export');hardwareReceive=false;$('transfer-log').textContent='Received and imported a DX7 bank from the FM-1.'}catch(e){toast(e.message)}}return}if(inputId!==inputChoice)return;const [status,n,v=0]=data,cmd=status&240;if(!$('synth-view').hidden){$('native-frame').contentWindow.postMessage({type:'external-midi',data:[status,n,v]},location.origin);return}try{if(!powered){toast('Click Switch on before playing your MIDI keyboard.');return}$('midi-led').style.color='#67ab3b';clearTimeout(receiveMidi.timer);receiveMidi.timer=setTimeout(()=>$('midi-led').style.color='#91a47f',120);if(settings.midiChannel&&((status&15)+1)!==settings.midiChannel)return;if(cmd===144&&v){sustained.delete(n);playNote(n,v,'midi',true,Number.isFinite(eventAt)&&Math.abs(now()-eventAt)<10000?eventAt:now())}else if(cmd===128||cmd===144&&!v)midiOff(n);else if(cmd===176&&n===64){sustain=v>=64;if(!sustain){for(const nn of sustained)releaseNote(nn,'midi',false);sustained.clear()}}else if(cmd===176&&(n===120||n===123))panic();else if(cmd===224){instrument.setBend(((v<<7|n)-8192)/8192)}else if(cmd===176&&n===1){instrument.lfo.depth=Math.round(v/127*60);instrument.updateLFO()}}catch(e){toast(e.message)}}
