$('receive-hardware').onclick=()=>{if(!midiAccess?.sysexEnabled||!$('hardware-input').value){toast('Enable SysEx and select the FM-1 response input.');return}hardwareReceive=true;$('transfer-log').textContent='Waiting for a standard DX7 dump from the selected input. On stock V16 use GLOBE → Export to send a stored bank. Close this panel to cancel.'};$('hardware-dialog').addEventListener('close',()=>{hardwareReceive=false});
$('export-voice').onclick=()=>{try{const i=requireInstrument();download(i.sysex(),selectedName.replace(/[^a-z0-9_-]/gi,'_')+'.syx')}catch(e){toast(e.message)}};
$('export-favorites').onclick=()=>{try{const selected=[...favorites].slice(0,32);if(!selected.length)throw Error('Favorite at least one patch first.');const voices=selected.map(i=>parseSysex(bytesAt(i)).voices[0].data);while(voices.length<32)voices.push(voices[0]);download(createBankSysex(voices),'FM1_favorites_32.syx');toast('Exported 32-slot bank. Unfilled slots repeat the first favorite; the file contains DX7 voice parameters only.')}catch(e){toast(e.message)}};
$('analog-sounds').replaceChildren(...ANALOG_PRESETS.map((p,i)=>{const b=document.createElement('button');b.textContent=p.name;b.onclick=async()=>{try{await analogPreset(i);$('library').close();setPage('EDIT')}catch(e){toast(e.message)}};return b}));
$('import-syx').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const bytes=new Uint8Array(await file.arrayBuffer());importBank(bytes,file.name);if(powered)await selectPatch(patchIndex);else{selectedName=patches[patchIndex].name;$('patch-label').textContent=selectedName+' / DX7';syncDesk()}}catch(err){toast('Patch import: '+err.message)}};
$('import-song').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{let l;if(/\.json$/i.test(file.name)){l=JSON.parse(await file.text());if(!l||!Array.isArray(l.events)||!l.events.length||l.events.length>15000)throw Error('Invalid lesson file');for(const v of l.events)if(!Number.isFinite(v.beat)||v.beat<0||!Number.isFinite(v.duration)||v.duration<=0||!Array.isArray(v.notes)||!v.notes.length||v.notes.some(n=>!Number.isInteger(n)||n<0||n>127))throw Error('Invalid notes or timing in lesson file');l={...l,id:'json-'+Date.now(),name:String(l.name||file.name).slice(0,80),group:'My songs',bpm:clamp(Number(l.bpm)||80,30,200),bars:Math.max(1,Math.ceil(Math.max(...l.events.map(e=>e.beat+e.duration))/4)),tip:'Imported practice song.'};}else l=parseMidi(await file.arrayBuffer(),file.name);addSong(l);$('lesson-library').close();toast('Imported '+l.events.length+' note events. Choose hands and a bar loop to practice.')}catch(err){toast('Song import: '+err.message)}};
$('sequence-to-lesson').onclick=()=>{try{addSong(sequenceLesson());toast('Your sequence is now a playable lesson.')}catch(e){toast(e.message)}};$('recording-to-lesson').onclick=()=>{try{if(recording)stopRecording();addSong(recordingLesson());toast('Your recorded performance is now a lesson.')}catch(e){toast(e.message)}};
$('sequence-run').onclick=async()=>{try{await switchOn();presetPicker.close();if(composer.playing){stopTransport();syncDesk()}else{setPage('SEQ');playSequence()}}catch(e){toast(e.message)}};
$('sequence-loop').onclick=()=>{composer.loop=!composer.loop;syncDesk()};
$('sequence-clear-step').onclick=()=>{composer.steps[composer.cursor]=[];syncDesk()};
$('sequence-example').onclick=async()=>{try{await switchOn();stopTransport();presetPicker.close();composer.steps=Array.from({length:64},()=>[]);composer.length=16;for(let i=0;i<16;i++)composer.steps[i]=i%4===0?[48,60,64,67]:[ [60,64,67,64][i%4] ];composer.cursor=0;setPage('SEQ');tell('Example loaded. Run sequence.');}catch(e){toast(e.message)}};
$('clear-sequence').onclick=()=>{stopTransport();composer.steps=Array.from({length:64},()=>[]);syncDesk();};$('save-song').onclick=()=>download(JSON.stringify(currentLesson(),null,2),currentLesson().name.replace(/[^a-z0-9_-]/gi,'_')+'.json','application/json');$('download-progress').onclick=()=>download(JSON.stringify({settings,progress},null,2),'FM1_practice_progress.json','application/json');
$('player-tab').onclick=()=>{setInstrumentMode('Player');$('coach-view').hidden=false;$('synth-view').hidden=true;$('synth-tab').classList.remove('active');$('native-frame').src='about:blank';instrument?.ac.resume()};
$('coach-tab').onclick=()=>{setInstrumentMode('Coach');$('coach-view').hidden=false;$('synth-view').hidden=true;$('coach-tab').classList.add('active');$('synth-tab').classList.remove('active');$('native-frame').src='about:blank';instrument?.ac.resume()};
$('synth-tab').onclick=()=>{stopTransport();arpSettings.enabled=false;clearTimeout(arpTimer);$('player-tab').classList.remove('active');recording=false;instrument?.ac.suspend();$('coach-view').hidden=true;$('synth-view').hidden=false;$('coach-tab').classList.remove('active');$('synth-tab').classList.add('active');$('native-frame').src='native/index.html'};
addEventListener('keydown',e=>{if(e.code==='Space'&&!e.repeat&&!e.target.closest('input,select,button,dialog')){e.preventDefault();if(powered)pressButton('PLAY')}});
addEventListener('blur',()=>{if(active&&!demo)for(const note of session.activeNotes.keys())session.noteOff(note,now());panic();lastMask=0;});
addEventListener('visibilitychange',()=>{if(document.hidden&&active&&!paused&&!demo&&!settings.backing){pauseLesson();automaticallyPaused=true;}else if(!document.hidden&&automaticallyPaused&&paused&&active){automaticallyPaused=false;pauseLesson();}});
try{const custom=JSON.parse(localStorage.getItem('fm1-custom-songs')||'[]');for(const l of custom)if(l.events?.length&&l.bars&&l.bars<10000)catalog.push(l)}catch{}
const requestedId=typeof location!=='undefined'?new URLSearchParams(location.search).get('lesson'):null;let initial=catalog.findIndex(l=>l.id===(requestedId||saved.lessonId));if(initial>=0){lessonIndex=initial;if(requestedId){settings.learningPlan=subjectOf(currentLesson());settings.loopStart=1;settings.loopEnd=currentLesson().bars;settings.bpm=currentLesson().bpm;}}else{settings.loopEnd=catalog[0].bars;}sanitizeSettings();syncSettings();renderLessons();syncDesk();libraryReady.catch(e=>toast(e.message));
$('record-performance').onclick=async()=>{try{await switchOn();if(recording)stopRecording();else startRecording();$('record-performance').textContent=recording?'Stop recording':'Record performance'}catch(e){toast(e.message)}};

$('next-practice').onclick=skipCoaching;

function syncBankStatus(){const location=currentPreset.kind==='DX7'?bankLocation(patchIndex):null;for(const id of ['A','B','C','D','Analog']){const selected=id==='Analog'?currentPreset.kind==='Analog':location?.id===id;$('quick-bank-'+id).setAttribute('aria-pressed',String(!!selected));}$('current-bank').textContent=currentPreset.kind==='Analog'?'ANALOG · '+selectedName:location?'BANK '+location.id+' · '+location.rom+' · '+String(location.slot).padStart(2,'0')+'/32 · '+selectedName:'DX7 LIBRARY · '+selectedName;}
async function chooseBank(id){await switchOn();if(active&&!paused&&!demo&&!settings.backing){pauseLesson();resumeAfterPreset=true;}const keepPractice=active&&paused&&!demo;category='Bank '+id;const bank=defaultBanks.find(b=>b.id===id);if(!bank)return;await selectPatch(bank.entries[0].patchIndex,{keepPractice});presetPicker.show(bank.entries.map(e=>({name:id+String(e.slot).padStart(2,'0')+' '+patches[e.patchIndex].name,index:e.patchIndex,kind:'DX7'})),0,now());syncBankStatus();tell('Bank '+id+' · PRESETS changes sound');}
for(const id of ['A','B','C','D'])$('quick-bank-'+id).onclick=()=>chooseBank(id).catch(e=>toast(e.message));
$('quick-bank-Moog').onclick=()=>{category='Moog-style FM';$('search').value='';renderLibrary();$('library').showModal();};
$('quick-bank-Analog').onclick=async()=>{try{await analogPreset(0);setPage('EDIT');presetPicker.show(ANALOG_PRESETS.map((p,i)=>({name:p.name,index:i,kind:'Analog'})),0,now());}catch(e){toast(e.message)}};
